		diagnostics = append(diagnostics, diags...)
	case *LocalVariable:
		diags := b.bindLocalVariable(node)
		diagnostics = append(diagnostics, diags...)
	case *Resource:
		diags := b.bindResource(ctx, node)
		diagnostics = append(diagnostics, diags...)
	case *Component:
		diags := b.bindComponent(node)
		diagnostics = append(diagnostics, diags...)
	case *OutputVariable:
		diags := b.bindOutputVariable(node)
		diagnostics = append(diagnostics, diags...)
	case *PulumiBlock:
		diags := b.bindPulumi(node)
		diagnostics = append(diagnostics, diags...)
